    "description": "<table class=\"spec-table\">\r\\n    <tbody>\r\\n        <tr>\r\\n            <th>Model</th>\r\\n            <td>AURA ORCHID (NORMAL + HOT)</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Application</th>\r\\n            <td>Suitable for Brackish Water</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Filter Life</th>\r\\n            <td>Approx. 3000 Litres / 6 Months</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Filters</th>\r\\n            <td>Sediment, Pre Carbon, Post Carbon</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Float</th>\r\\n            <td>Membrella</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>FR</th>\r\\n            <td>Membrella / KFL</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Inline Set</th>\r\\n            <td>Membrella</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Input Voltage</th>\r\\n            <td>100–300V AC (50Hz)</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Installation</th>\r\\n            <td>Counter Top</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Maximum Operating TDS</th>\r\\n            <td>Up to 3000 PPM</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Membrane Type</th>\r\\n            <td>Thin Film Composite (TFC)</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Minimum Inlet Pressure / Temperature</th>\r\\n            <td>0.3 kg/cm², 10°C</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Operating Voltage</th>\r\\n            <td>24V DC</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Purification Capacity</th>\r\\n            <td>12 Litres Per Hour</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Recovery Rate</th>\r\\n            <td>More than 30% at 27°C ± 2°C</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>SMPS</th>\r\\n            <td>Membrella</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Solenoid Valve</th>\r\\n            <td>Membrella / SLX</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Storage Capacity</th>\r\\n            <td>8 Litres</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Hot Water Capacity</th>\r\\n            <td>1 Litre</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Technology</th>\r\\n            <td>Reverse Osmosis (RO) System</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Total Power Consumption</th>\r\\n            <td>50 W</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Tubing</th>\r\\n            <td>5 Metres</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>System Weight</th>\r\\n            <td>6.6 kg (Approx.)</td>\r\\n        </tr>\r\\n        <tr>\r\\n            <th>Country of Origin</th>\r\\n            <td>India</td>\r\\n        </tr>\r\\n    </tbody>\r\\n</table>",
